#!/usr/bin/env bash
# Final measurements: three regions (640 x 640 blocks) generated by the real engine with four builds of the pack:
#   precaves = the pack before this round (vanilla Plains caves), nocaves = no caves, noore = caves, ore = caves and ore.
cd "$(dirname "$0")/../.."
J="$HOME/.jdks/loom-ea-25-loom+1-11/bin"; O=tools/worldscan/out
run() {
  for v in precaves nocaves noore ore; do
    bash tools/worldscan/scan.sh "$1_$v" "$2" "$3" "$4" 640 640 "$O/mod_$v.jar" 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | grep -E "generated|exited" > "$O/$1_$v.genF.txt"
  done
  "$J/java" -Xmx8g tools/worldscan/WorldAnalyze.java "$(cygpath -w $O/$1_ore/scan.bin)" "$(cygpath -w $O/$1_noore/scan.bin)" > "$O/$1_ore.analysisF.txt" 2>&1
  "$J/java" -Xmx8g tools/worldscan/WorldAnalyze.java "$(cygpath -w $O/$1_noore/scan.bin)" "$(cygpath -w $O/$1_nocaves/scan.bin)" > "$O/$1_noore.analysisF.txt" 2>&1
  rm -f "$O/$1_precaves/scan.bin" "$O/$1_nocaves/scan.bin"
}
run A 1791432644696 -1696 256
run B 42 0 -1920
run C 1791436655886 352 -800
echo finished > "$O/batchfinal.done"
